{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE `geek-maplemonk.maplemonk.geek_maplemonk_todays_pulse` AS WITH daily AS ( SELECT DATE(s.date) AS date, \'WEBSITE\' AS segment, SUM(CASE WHEN s.marketplace = \'WEBSITE\' THEN s.Total_Sales_EXCL_CANCL END) AS total_sales, SUM(CASE WHEN s.marketplace = \'WEBSITE\' THEN s.Orders_EXCL_CANCL END) AS total_orders, SUM(CASE WHEN s.marketplace = \'WEBSITE\' THEN s.sessions END) AS total_sessions, SUM(CASE WHEN s.marketplace = \'WEBSITE\' THEN s.marketing_spend END) AS total_spend, SUM(CASE WHEN s.marketplace = \'WEBSITE\' THEN s.ad_clicks END) AS total_clicks, SUM(CASE WHEN s.marketplace = \'WEBSITE\' THEN s.ad_impressions END) AS total_impressions FROM `geek-maplemonk.maplemonk.geek_maplemonk_Sales_Cost_Source` s GROUP BY 1, 2 UNION ALL SELECT DATE(s.date) AS date, \'MARKETPLACE\' AS segment, SUM(CASE WHEN s.marketplace != \'WEBSITE\' THEN s.Total_Sales_EXCL_CANCL END), SUM(CASE WHEN s.marketplace != \'WEBSITE\' THEN s.Orders_EXCL_CANCL END), SUM(CASE WHEN s.marketplace != \'WEBSITE\' THEN s.sessions END), SUM(CASE WHEN s.marketplace != \'WEBSITE\' THEN s.marketing_spend END), SUM(CASE WHEN s.marketplace != \'WEBSITE\' THEN s.ad_clicks END), SUM(CASE WHEN s.marketplace != \'WEBSITE\' THEN s.ad_impressions END) FROM `geek-maplemonk.maplemonk.geek_maplemonk_Sales_Cost_Source` s GROUP BY 1, 2 UNION ALL SELECT DATE(s.date) AS date, \'COMBINED\' AS segment, SUM(s.Total_Sales_EXCL_CANCL), SUM(s.Orders_EXCL_CANCL), SUM(s.sessions), SUM(s.marketing_spend), SUM(s.ad_clicks), SUM(s.ad_impressions) FROM `geek-maplemonk.maplemonk.geek_maplemonk_Sales_Cost_Source` s GROUP BY 1, 2 ), targets AS ( SELECT CAST(Year AS INT64) AS yr, EXTRACT(MONTH FROM PARSE_DATE(\'%b\', Month)) AS mth, SUM(SAFE_CAST(NULLIF(REPLACE(Revenue, \',\', \'\'), \'-\') AS FLOAT64)) AS target_revenue, SUM(SAFE_CAST(NULLIF(REPLACE(Budget, \',\', \'\'), \'-\') AS FLOAT64)) AS target_adspend, SUM(SAFE_CAST(NULLIF(REPLACE(Units, \',\', \'\'), \'-\') AS FLOAT64)) AS target_quantity FROM `geek-maplemonk.maplemonk.geektech_gs_Monthly_Targets` GROUP BY 1, 2 ), mtd AS ( SELECT d1.date AS pulse_date, d1.segment AS segment, SUM(d2.total_sales) AS mtd_sales, SUM(d2.total_orders) AS mtd_orders, SUM(d2.total_sessions) AS mtd_sessions, SUM(d2.total_spend) AS mtd_spend, SUM(d2.total_clicks) AS mtd_clicks, SUM(d2.total_impressions) AS mtd_impressions FROM daily d1 JOIN daily d2 ON d2.date BETWEEN DATE_TRUNC(d1.date, MONTH) AND d1.date AND d2.segment = d1.segment GROUP BY 1, 2 ) SELECT d.date AS pulse_date, d.segment, d.total_sales AS sales_today, d.total_orders AS orders_today, ROUND(SAFE_DIVIDE(d.total_sales, d.total_orders), 0) AS aov_today, d.total_spend AS spend_today, ROUND(SAFE_DIVIDE(d.total_spend, d.total_sales) * 100, 2) AS tacos_today, d.total_sessions AS sessions_today, ROUND(SAFE_DIVIDE(d.total_spend, d.total_clicks), 2) AS cpc_today, ROUND(SAFE_DIVIDE(d.total_clicks, d.total_impressions) * 100, 2) AS ctr_today, ROUND(SAFE_DIVIDE(d.total_orders, d.total_sessions) * 100, 2) AS cvr_today, yd.total_sales AS sales_yday, yd.total_orders AS orders_yday, ROUND(SAFE_DIVIDE(yd.total_sales, yd.total_orders), 0) AS aov_yday, yd.total_spend AS spend_yday, ROUND(SAFE_DIVIDE(yd.total_spend, yd.total_sales) * 100, 2) AS tacos_yday, yd.total_sessions AS sessions_yday, ROUND(SAFE_DIVIDE(yd.total_spend, yd.total_clicks), 2) AS cpc_yday, ROUND(SAFE_DIVIDE(yd.total_clicks, yd.total_impressions) * 100, 2) AS ctr_yday, ROUND(SAFE_DIVIDE(yd.total_orders, yd.total_sessions) * 100, 2) AS cvr_yday, m.mtd_sales AS sales_mtd, m.mtd_orders AS orders_mtd, ROUND(SAFE_DIVIDE(m.mtd_sales, m.mtd_orders), 0) AS aov_mtd, m.mtd_spend AS spend_mtd, ROUND(SAFE_DIVIDE(m.mtd_spend, m.mtd_sales) * 100, 2) AS tacos_mtd, m.mtd_sessions AS sessions_mtd, ROUND(SAFE_DIVIDE(m.mtd_spend, m.mtd_clicks), 2) AS cpc_mtd, ROUND(SAFE_DIVIDE(m.mtd_clicks, m.mtd_impressions) * 100, 2) AS ctr_mtd, ROUND(SAFE_DIVIDE(m.mtd_orders, m.mtd_sessions) * 100, 2) AS cvr_mtd, t.target_revenue, t.target_adspend, t.target_quantity FROM daily d LEFT JOIN daily yd ON yd.date = DATE_SUB(d.date, INTERVAL 1 DAY) AND yd.segment = d.segment LEFT JOIN mtd m ON m.pulse_date = d.date AND m.segment = d.segment LEFT JOIN targets t ON EXTRACT(YEAR FROM d.date) = t.yr AND EXTRACT(MONTH FROM d.date) = t.mth ORDER BY d.date DESC, d.segment; CREATE OR REPLACE TABLE `geek-maplemonk.maplemonk.todays_pulse_display` AS SELECT pulse_date, segment, \'Total Revenue (₹)\' AS metric, 1 AS sort_order, sales_today AS today, sales_yday AS yesterday, sales_mtd AS mtd, target_revenue AS target FROM `geek-maplemonk.maplemonk.geek_maplemonk_todays_pulse` UNION ALL SELECT pulse_date, segment, \'Total Orders\', 2, orders_today, orders_yday, orders_mtd, target_quantity FROM `geek-maplemonk.maplemonk.geek_maplemonk_todays_pulse` UNION ALL SELECT pulse_date, segment, \'AOV (₹)\', 3, aov_today, aov_yday, aov_mtd, NULL FROM `geek-maplemonk.maplemonk.geek_maplemonk_todays_pulse` UNION ALL SELECT pulse_date, segment, \'Adv. Spend (₹)\', 4, spend_today, spend_yday, spend_mtd, target_adspend FROM `geek-maplemonk.maplemonk.geek_maplemonk_todays_pulse` UNION ALL SELECT pulse_date, segment, \'TaCOS (%)\', 5, tacos_today, tacos_yday, tacos_mtd, NULL FROM `geek-maplemonk.maplemonk.geek_maplemonk_todays_pulse` UNION ALL SELECT pulse_date, segment, \'Page Views\', 6, sessions_today, sessions_yday, sessions_mtd, NULL FROM `geek-maplemonk.maplemonk.geek_maplemonk_todays_pulse` UNION ALL SELECT pulse_date, segment, \'CPC (₹)\', 7, cpc_today, cpc_yday, cpc_mtd, NULL FROM `geek-maplemonk.maplemonk.geek_maplemonk_todays_pulse` UNION ALL SELECT pulse_date, segment, \'CTR (%)\', 8, ctr_today, ctr_yday, ctr_mtd, NULL FROM `geek-maplemonk.maplemonk.geek_maplemonk_todays_pulse` UNION ALL SELECT pulse_date, segment, \'Conversion Rate (%)\', 9, cvr_today, cvr_yday, cvr_mtd, NULL FROM `geek-maplemonk.maplemonk.geek_maplemonk_todays_pulse` ORDER BY pulse_date DESC, segment, sort_order;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
